const flat = $input.first().json;
const job = $('Get job spec').first().json;
const email = $('Gmail Trigger').first();

return [{
  json: {
    ...flat,
    job_ref: String(flat.job_ref ?? '').trim(),
    zoho_job_id: String(job.zoho_job_id ?? '').trim(),
    zoho_client_id: String(job.zoho_client_id ?? '').trim(),
    cv_filename: email.binary?.attachment_0?.fileName ?? 'cv.pdf'
  },
  binary: email.binary
}];

// Build approval card - consultant-facing email in the OpsAutomated email design system (same tokens as the digest).
// Buttons go to the decision gateway (M3b) with the approval token; state lives in ops.approvals, not in this execution.
const c = $("Call 'ATS adapter - Zoho'").item.json;
const cfg = $('Config').item.json;
const job = $('Get job spec').item.json;
const token = $input.first().json.token;
const hooks = (cfg.hooks_base || 'https://hooks.example.com').replace(/\/$/, '');

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const font = "-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif";
const ink = cfg.brand_ink || '#111827', primary = cfg.brand_primary || '#0ea672';
const muted = '#6b7280', faint = '#9ca3af', line = '#e5e7eb', bg = '#f3f4f6';
const bands = { A: { bg: '#d1fae5', fg: '#065f46' }, B: { bg: '#fef3c7', fg: '#92400e' }, C: { bg: '#e5e7eb', fg: '#374151' } };
const band = bands[String(c.band || '').toUpperCase()] ? String(c.band).toUpperCase() : 'C';
const b = bands[band];
const first = String(c.full_name || '').trim().split(/\s+/)[0] || 'the candidate';
const agency = cfg.agency_name || 'Your agency';
const ats = cfg.ats_label || 'ATS';
const flags = String(c.flags || '').split(/[;,|]\s*/).map(s => s.trim()).filter(f => f && !/^none$/i.test(f));
const role = [c.current_title, c.current_employer].filter(Boolean).join(' at ');
const skills = String(c.key_skills || '').split(/,\s*/).filter(Boolean);
const skillsText = skills.length > 8 ? skills.slice(0, 8).join(', ') + ` and ${skills.length - 8} more` : skills.join(', ');
const received = (() => { const t = new Date(c.received_at); return isNaN(t) ? '' : t.toLocaleString('en-GB', { weekday: 'short', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit', timeZone: 'Europe/London' }); })();
const approveUrl = `${hooks}/webhook/decide?t=${encodeURIComponent(token)}&d=approve`;
const holdUrl = `${hooks}/webhook/decide?t=${encodeURIComponent(token)}&d=hold`;

const fact = (k, v) => `<tr><td style="padding:6px 12px 6px 0;font:13px/1.4 ${font};color:${muted};width:120px;vertical-align:top;white-space:nowrap;">${esc(k)}</td><td style="padding:6px 0;font:14px/1.4 ${font};color:${ink};">${esc(v || 'not stated')}</td></tr>`;

const html = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(agency)}</title></head>
<body style="margin:0;padding:0;background:${bg};">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:${bg};">
<tr><td align="center" style="padding:0 0 32px;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;">
  <tr><td><div style="height:4px;background:${primary};border-radius:0 0 2px 2px;"></div></td></tr>
  <tr><td style="padding:22px 20px 14px;">
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>
      <td style="font:700 15px/1 ${font};color:${ink};">${esc(agency)}</td>
      <td align="right" style="font:13px/1 ${font};color:${muted};">New application</td>
    </tr></table>
  </td></tr>
  <tr><td style="padding:0 20px;">
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#ffffff;border:1px solid ${line};border-radius:12px;">
      <tr><td style="padding:20px 20px 0;">
        <div style="font:600 11px/1 ${font};letter-spacing:.08em;text-transform:uppercase;color:${faint};">${esc(c.job_ref)}</div>
        <div style="margin-top:4px;font:700 20px/1.25 ${font};color:${ink};letter-spacing:-.01em;">${esc(job.title || 'Role')}</div>
      </td></tr>
      <tr><td style="padding:18px 20px 0;">
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>
          <td width="56" valign="top" style="padding-right:14px;"><div style="width:56px;height:56px;border-radius:12px;background:${b.bg};color:${b.fg};font:700 22px/56px ${font};text-align:center;">${esc(c.fit_score)}</div></td>
          <td valign="top">
            <div style="font:600 18px/1.3 ${font};color:${ink};">${esc(c.full_name)}</div>
            ${role ? `<div style="margin-top:2px;font:13px/1.4 ${font};color:${muted};">${esc(role)}</div>` : ''}
            <div style="margin-top:8px;"><span style="display:inline-block;padding:3px 9px;border-radius:999px;background:${b.bg};color:${b.fg};font:600 11px/1 ${font};letter-spacing:.06em;text-transform:uppercase;">Band ${band}</span>${received ? ` <span style="font:12px/1 ${font};color:${faint};padding-left:6px;">Applied ${esc(received)}</span>` : ''}</div>
          </td>
        </tr></table>
      </td></tr>
      <tr><td style="padding:16px 20px 0;font:15px/1.55 ${font};color:${ink};">${esc(c.rationale)}</td></tr>
      ${flags.length ? `<tr><td style="padding:12px 20px 0;"><table role="presentation" cellpadding="0" cellspacing="0"><tr><td style="padding:6px 10px;border-radius:6px;background:#fff7ed;border:1px solid #fed7aa;font:13px/1.4 ${font};color:#9a3412;">${flags.map(esc).join(' &nbsp;&middot;&nbsp; ')}</td></tr></table></td></tr>` : ''}
      <tr><td style="padding:16px 20px 0;">
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-top:1px solid ${line};">
          <tr><td colspan="2" style="height:8px;font-size:0;">&nbsp;</td></tr>
          ${fact('Location', c.location)}
          ${fact('Experience', c.years_experience ? c.years_experience + ' years' : '')}
          ${fact('Salary', c.salary_expectation)}
          ${fact('Right to work', c.right_to_work)}
          ${fact('Skills', skillsText)}
        </table>
        ${c.zoho_candidate_url ? `<div style="margin-top:10px;font:13px/1.4 ${font};color:${muted};">Filed in ${esc(ats)} with the CV and a note. <a href="${esc(c.zoho_candidate_url)}" style="color:${primary};text-decoration:none;font-weight:600;">Open in ${esc(ats)} &rarr;</a></div>` : ''}
      </td></tr>
      <tr><td style="padding:20px 20px 20px;">
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>
          <td style="padding-right:8px;"><a href="${esc(approveUrl)}" style="display:block;padding:13px 16px;border-radius:8px;background:${ink};color:#ffffff;font:600 14px/1 ${font};text-align:center;text-decoration:none;">Reply to ${esc(first)}</a></td>
          <td width="110"><a href="${esc(holdUrl)}" style="display:block;padding:12px 16px;border-radius:8px;border:1px solid ${line};background:#ffffff;color:${ink};font:600 14px/1 ${font};text-align:center;text-decoration:none;">Hold</a></td>
        </tr></table>
        <div style="margin-top:10px;font:12px/1.5 ${font};color:${faint};">Reply sends ${esc(first)} the Band ${band} acknowledgement from ${esc(agency)}, with you as reply-to. Nothing is sent until you choose. Hold keeps ${esc(first)} in the digest until you decide.</div>
      </td></tr>
    </table>
  </td></tr>
  <tr><td style="padding:12px 20px 0;font:12px/1.6 ${font};color:${faint};">Run for ${esc(agency)} by OpsAutomated.</td></tr>
</table>
</td></tr></table></body></html>`;

const subject = `${band === 'A' ? '\u{1F525} ' : ''}Band ${band} · ${c.full_name} for ${c.job_ref} (${c.fit_score}/10)`;
return [{ json: { to: cfg.consultant_email, subject, html, approveUrl, holdUrl, token } }];
